selector_to_html = {"a[href=\"#filter-by-diameter\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Filter by Diameter<a class=\"headerlink\" href=\"#filter-by-diameter\" title=\"Link to this heading\">#</a></h4><p>Remove ROIs with abnormal sizes:</p>", "a[href=\"#median-filter-baseline\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Median Filter Baseline<a class=\"headerlink\" href=\"#median-filter-baseline\" title=\"Link to this heading\">#</a></h3><p>A simpler alternative for stable recordings:</p>", "a[href=\"#load-ops\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Load Ops<a class=\"headerlink\" href=\"#load-ops\" title=\"Link to this heading\">#</a></h3><p>Simple utility to load ops.npy:</p>", "a[href=\"#fig-dff-window\"]": "<figure class=\"align-default\" id=\"fig-dff-window\">\n<a class=\"reference internal image-reference\" href=\"_images/dff_window_size_effect.png\"><img alt=\"Effect of window size on dF/F\" src=\"_images/dff_window_size_effect.png\" style=\"width: 100%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\">Effect of window size on \u0394F/F calculation. Smaller windows track faster baseline changes but may contaminate baseline with transients. Larger windows provide stable baselines but miss slow drifts.</span><a class=\"headerlink\" href=\"#fig-dff-window\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#default-filter-behavior\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Default Filter Behavior<a class=\"headerlink\" href=\"#default-filter-behavior\" title=\"Link to this heading\">#</a></h4><p>By default, if pixel resolution is available in the metadata, <code class=\"docutils literal notranslate\"><span class=\"pre\">lsp.pipeline()</span></code> applies a diameter filter of <strong>4-35 \u00b5m</strong>:</p>", "a[href=\"#event-exceptionality\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Event Exceptionality<a class=\"headerlink\" href=\"#event-exceptionality\" title=\"Link to this heading\">#</a></h3><p>Identify neurons with exceptional (rare) events using the method from Suite2p:</p>", "a[href=\"#window-size-effect\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Window Size Effect<a class=\"headerlink\" href=\"#window-size-effect\" title=\"Link to this heading\">#</a></h3><p>The window size critically affects baseline estimation:</p>", "a[href=\"#disable-all-filtering\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Disable All Filtering<a class=\"headerlink\" href=\"#disable-all-filtering\" title=\"Link to this heading\">#</a></h4><p>To skip all cell filters, pass an empty list:</p>", "a[href=\"#fig-exceptionality\"]": "<figure class=\"align-default\" id=\"fig-exceptionality\">\n<a class=\"reference internal image-reference\" href=\"_images/event_exceptionality.png\"><img alt=\"Event exceptionality detection\" src=\"_images/event_exceptionality.png\" style=\"width: 100%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\">Event exceptionality analysis. The fitness score distribution shows most neurons have moderate exceptionality. Lower fitness scores indicate neurons with rarer, more exceptional events. The trace panel shows the 5 most exceptional neurons (lowest fitness scores) with best-quality neurons displayed at top.</span><a class=\"headerlink\" href=\"#fig-exceptionality\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"processing_flow.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Processing Flow<a class=\"headerlink\" href=\"#processing-flow\" title=\"Link to this heading\">#</a></h1><p>High-level overview of all processing steps executed by <code class=\"docutils literal notranslate\"><span class=\"pre\">lsp.pipeline()</span></code>.</p>", "a[href=\"#fig-quality-score\"]": "<figure class=\"align-default\" id=\"fig-quality-score\">\n<a class=\"reference internal image-reference\" href=\"_images/quality_score_breakdown.png\"><img alt=\"Quality score breakdown\" src=\"_images/quality_score_breakdown.png\" style=\"width: 100%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\">Quality score component distributions (SNR, skewness, shot noise) and example traces. The bottom panel shows top 5 quality neurons (cyan, top) vs bottom 5 quality neurons (red, bottom).</span><a class=\"headerlink\" href=\"#fig-quality-score\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#normalized-traces-output\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Normalized traces output<a class=\"headerlink\" href=\"#normalized-traces-output\" title=\"Link to this heading\">#</a></h3><p>The pipeline writes the normalized trace to <code class=\"docutils literal notranslate\"><span class=\"pre\">norm_traces.npy</span></code>. Choose the method with <code class=\"docutils literal notranslate\"><span class=\"pre\">norm_method</span></code>:</p>", "a[href=\"#export-utilities\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Export Utilities<a class=\"headerlink\" href=\"#export-utilities\" title=\"Link to this heading\">#</a></h2><h3>Ops to JSON<a class=\"headerlink\" href=\"#ops-to-json\" title=\"Link to this heading\">#</a></h3><p>Export ops dictionary to JSON for reproducibility:</p>", "a[href=\"#filter-summary-figures\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Filter Summary Figures<a class=\"headerlink\" href=\"#filter-summary-figures\" title=\"Link to this heading\">#</a></h3><p>When filters reject cells, the pipeline generates diagnostic figures:</p><p><strong>Planar outputs</strong> (in each plane directory):</p>", "a[href=\"#combined-filtering-example\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Combined Filtering Example<a class=\"headerlink\" href=\"#combined-filtering-example\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#custom-filters-via-cell-filters\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Custom Filters via cell_filters<a class=\"headerlink\" href=\"#custom-filters-via-cell-filters\" title=\"Link to this heading\">#</a></h4><p>Override the default with the <code class=\"docutils literal notranslate\"><span class=\"pre\">cell_filters</span></code> parameter:</p>", "a[href=\"#sort-traces-by-quality\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Sort Traces by Quality<a class=\"headerlink\" href=\"#sort-traces-by-quality\" title=\"Link to this heading\">#</a></h3><p>Convenience function to sort traces:</p>", "a[href=\"#filter-by-area\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Filter by Area<a class=\"headerlink\" href=\"#filter-by-area\" title=\"Link to this heading\">#</a></h3><p>Filter based on pixel count:</p>", "a[href=\"#data-loaders\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Data Loaders<a class=\"headerlink\" href=\"#data-loaders\" title=\"Link to this heading\">#</a></h2><h3>Load Planar Results<a class=\"headerlink\" href=\"#load-planar-results\" title=\"Link to this heading\">#</a></h3><p>Load all Suite2p outputs from a plane directory:</p>", "a[href=\"#available-filters\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Available Filters<a class=\"headerlink\" href=\"#available-filters\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#noise-estimation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Noise Estimation<a class=\"headerlink\" href=\"#noise-estimation\" title=\"Link to this heading\">#</a></h2><h3>Shot Noise<a class=\"headerlink\" href=\"#shot-noise\" title=\"Link to this heading\">#</a></h3><p>Quantify recording quality using standardized shot noise levels:</p>", "a[href=\"#shot-noise\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Shot Noise<a class=\"headerlink\" href=\"#shot-noise\" title=\"Link to this heading\">#</a></h3><p>Quantify recording quality using standardized shot noise levels:</p>", "a[href=\"#f-f-calculation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u0394F/F Calculation<a class=\"headerlink\" href=\"#f-f-calculation\" title=\"Link to this heading\">#</a></h2><h3>Rolling Percentile Baseline<a class=\"headerlink\" href=\"#rolling-percentile-baseline\" title=\"Link to this heading\">#</a></h3><p>The recommended method for computing \u0394F/F\u2080 uses a rolling percentile baseline that adapts to slow drifts in fluorescence:</p>", "a[href=\"#pipeline-integrated-filtering\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Pipeline-Integrated Filtering<a class=\"headerlink\" href=\"#pipeline-integrated-filtering\" title=\"Link to this heading\">#</a></h3><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">lsp.pipeline()</span></code> function automatically applies cell filters after suite2p detection. This is the recommended approach for most workflows.</p>", "a[href=\"pipeline_comparison.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Pipeline Comparison<a class=\"headerlink\" href=\"#pipeline-comparison\" title=\"Link to this heading\">#</a></h1><p>This page compares how different calcium imaging analysis pipelines handle \u0394F/F calculation, neuropil correction, and spike deconvolution.</p>", "a[href=\"#postprocessing-functions\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Postprocessing Functions<a class=\"headerlink\" href=\"#postprocessing-functions\" title=\"Link to this heading\">#</a></h1><p>This guide covers the postprocessing functions available in LBM-Suite2p-Python for analyzing and refining calcium imaging traces after Suite2p extraction.</p>", "a[href=\"#fig-trace-sorting\"]": "<figure class=\"align-default\" id=\"fig-trace-sorting\">\n<a class=\"reference internal image-reference\" href=\"_images/trace_sorting_comparison.png\"><img alt=\"Trace sorting comparison\" src=\"_images/trace_sorting_comparison.png\" style=\"width: 100%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\">Comparison of traces in original order (left) vs sorted by quality score (right). Quality-sorted display shows best neurons at top with color gradient from high quality (yellow) to lower quality (purple).</span><a class=\"headerlink\" href=\"#fig-trace-sorting\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#accept-all-cells-parameter\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">accept_all_cells Parameter<a class=\"headerlink\" href=\"#accept-all-cells-parameter\" title=\"Link to this heading\">#</a></h3><p>Suite2p\u2019s internal classifier may reject ROIs based on morphological properties. Use <code class=\"docutils literal notranslate\"><span class=\"pre\">accept_all_cells=True</span></code> to accept all detected ROIs regardless of suite2p\u2019s classification:</p>", "a[href=\"#fig-shot-noise\"]": "<figure class=\"align-default\" id=\"fig-shot-noise\">\n<a class=\"reference internal image-reference\" href=\"_images/shot_noise_analysis.png\"><img alt=\"Shot noise analysis\" src=\"_images/shot_noise_analysis.png\" style=\"width: 100%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\">Shot noise distribution comparing accepted vs rejected cells. Lower noise indicates cleaner recordings. The trace panel shows example neurons with low noise (cyan, top) vs high noise (red, bottom).</span><a class=\"headerlink\" href=\"#fig-shot-noise\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#compute-trace-quality-score\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Compute Trace Quality Score<a class=\"headerlink\" href=\"#compute-trace-quality-score\" title=\"Link to this heading\">#</a></h3><p>Combine multiple metrics to rank neurons by signal quality:</p>", "a[href=\"#rolling-percentile-baseline\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Rolling Percentile Baseline<a class=\"headerlink\" href=\"#rolling-percentile-baseline\" title=\"Link to this heading\">#</a></h3><p>The recommended method for computing \u0394F/F\u2080 uses a rolling percentile baseline that adapts to slow drifts in fluorescence:</p>", "a[href=\"#quality-scoring\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Quality Scoring<a class=\"headerlink\" href=\"#quality-scoring\" title=\"Link to this heading\">#</a></h2><h3>Compute Trace Quality Score<a class=\"headerlink\" href=\"#compute-trace-quality-score\" title=\"Link to this heading\">#</a></h3><p>Combine multiple metrics to rank neurons by signal quality:</p>", "a[href=\"#complete-workflow-example\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Complete Workflow Example<a class=\"headerlink\" href=\"#complete-workflow-example\" title=\"Link to this heading\">#</a></h2>", "a[href=\"user_guide.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">User Guide<a class=\"headerlink\" href=\"#user-guide\" title=\"Link to this heading\">#</a></h1><p>For</p>", "a[href=\"#ops-to-json\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Ops to JSON<a class=\"headerlink\" href=\"#ops-to-json\" title=\"Link to this heading\">#</a></h3><p>Export ops dictionary to JSON for reproducibility:</p>", "a[href=\"#event-detection\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Event Detection<a class=\"headerlink\" href=\"#event-detection\" title=\"Link to this heading\">#</a></h2><h3>Event Exceptionality<a class=\"headerlink\" href=\"#event-exceptionality\" title=\"Link to this heading\">#</a></h3><p>Identify neurons with exceptional (rare) events using the method from Suite2p:</p>", "a[href=\"#manual-filter-functions\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Manual Filter Functions<a class=\"headerlink\" href=\"#manual-filter-functions\" title=\"Link to this heading\">#</a></h3><p>For fine-grained control, use the individual filter functions:</p>", "a[href=\"#programmatic-filtering-with-apply-filters\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Programmatic Filtering with apply_filters<a class=\"headerlink\" href=\"#programmatic-filtering-with-apply-filters\" title=\"Link to this heading\">#</a></h3><p>For more control, use <code class=\"docutils literal notranslate\"><span class=\"pre\">apply_filters()</span></code> directly:</p>", "a[href=\"#z-score\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Z-Score<a class=\"headerlink\" href=\"#z-score\" title=\"Link to this heading\">#</a></h3><p>As an alternative to \u0394F/F, traces can be z-scored per ROI (<code class=\"docutils literal notranslate\"><span class=\"pre\">(F</span> <span class=\"pre\">-</span> <span class=\"pre\">mean)</span> <span class=\"pre\">/</span> <span class=\"pre\">std</span></code> over time):</p>", "a[href=\"#fig-dff-methods\"]": "<figure class=\"align-default\" id=\"fig-dff-methods\">\n<a class=\"reference internal image-reference\" href=\"_images/dff_methods_comparison.png\"><img alt=\"Comparison of dF/F methods\" src=\"_images/dff_methods_comparison.png\" style=\"width: 100%;\"/>\n</a>\n<figcaption>\n<p><span class=\"caption-text\">Comparison of different \u0394F/F calculation methods. Rolling percentile (20th) provides robust baseline estimation that handles slow drifts while preserving transient peaks.</span><a class=\"headerlink\" href=\"#fig-dff-methods\" title=\"Link to this image\">#</a></p>\n</figcaption>\n</figure>", "a[href=\"#load-traces-accepted-only\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Load Traces (Accepted Only)<a class=\"headerlink\" href=\"#load-traces-accepted-only\" title=\"Link to this heading\">#</a></h3><p>Load only accepted cell traces:</p>", "a[href=\"#filter-by-eccentricity\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Filter by Eccentricity<a class=\"headerlink\" href=\"#filter-by-eccentricity\" title=\"Link to this heading\">#</a></h3><p>Remove elongated ROIs that are likely not cell bodies:</p>", "a[href=\"#load-planar-results\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Load Planar Results<a class=\"headerlink\" href=\"#load-planar-results\" title=\"Link to this heading\">#</a></h3><p>Load all Suite2p outputs from a plane directory:</p>", "a[href=\"#roi-filtering\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">ROI Filtering<a class=\"headerlink\" href=\"#roi-filtering\" title=\"Link to this heading\">#</a></h2><h3>Pipeline-Integrated Filtering<a class=\"headerlink\" href=\"#pipeline-integrated-filtering\" title=\"Link to this heading\">#</a></h3><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">lsp.pipeline()</span></code> function automatically applies cell filters after suite2p detection. This is the recommended approach for most workflows.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
